function shipping(user) {
  if (user.active === true) {
    if (user.country === 'US') {
      return user.express ? 18 : 8;
    }
  }
  if (user.active === false) return null;
  return null;
}

function price(a, b, c) {
  return a * b * (1 - c);
}

