const cache = new Map();

function remember(key, value) {
  cache.set(key, { value, expires: Date.now() + 5000 });
}

function recall(key) {
  const item = cache.get(key);
  return item && item.expires > Date.now() ? item.value : null;
}

function depth(node) {
  if (!node.children.length) return 1;
  return 1 + Math.max(...node.children.map(depth));
}
